    static void backtrack(int[][] grid, int x, int y, int remaining) {
        if (remaining == 0) {
            int free = 0;
            for (int i = 0; i < n; i++)
                for (int j = 0; j < m; j++)
                    if (grid[i][j] == 0) free++;
            maxFree = Math.max(maxFree, free);
            return;
        }
        if (x >= n) return;
        int nx = x, ny = y + 1;
        if (ny >= m) { nx++; ny = 0; }
        for (int[] d : dirs) {
            int tx = x + d[0], ty = y + d[1];
            if (tx < 0 || ty < 0 || tx >= n || ty >= m) continue;
            if (grid[tx][ty] > 0) {
                grid[x][y]--;
                grid[tx][ty]++;
                backtrack(grid, nx, ny, remaining - 1);
                grid[x][y]++;
                grid[tx][ty]--;
            }
        }
    }
