        ng[row][col] = 0;
        solve(nextRow, nextCol, ng);
        // Up
        if (row - 1 >= 0) {
            ng = copy(g);
            ng[row][col] = 0;
            ng[row-1][col] = 0;
            solve(nextRow, nextCol, ng);
        }
        // Down
        if (row + 1 < n) {
            ng = copy(g);
            ng[row][col] = 0;
            ng[row+1][col] = 0;
            solve(nextRow, nextCol, ng);
        }
        // Left
        if (col - 1 >= 0) {
            ng = copy(g);
            ng[row][col] = 0;
            ng[row][col-1] = 0;
            solve(nextRow, nextCol, ng);
